func reverse(x int) int {
    org := x
    x = abs(x)
    res := 0

    for x > 0 {
        res = res*10 + x%10
        x /= 10
    }

    if org < 0 {
        res = -res
    }
    if res < -(1 << 31) || res > (1<<31)-1 {
        return 0
    }
    return res
}

func abs(x int) int {
    if x < 0 {
        return -x
    }
    return x
}
```

```kotlin
class Solution {
    fun reverse(x: Int): Int {
        val org = x
        var num = Math.abs(x)
        var res = 0

        while (num > 0) {
            if (res > (Int.MAX_VALUE - num % 10) / 10) {
                return 0
            }
            res = res * 10 + num % 10
            num /= 10
        }

        if (org < 0) {
            res = -res
        }
        return if (res < Int.MIN_VALUE || res > Int.MAX_VALUE) 0 else res
    }
}
```

