    func reverse(_ x: Int) -> Int {
        let org = x
        var x = abs(x)
        var res = Int(String(String(x).reversed()))!

        if org < 0 {
            res *= -1
        }
        if res < Int32.min || res > Int32.max {
            return 0
        }

        return res
    }
}
```

