impl Solution {
    pub fn reverse(x: i32) -> i32 {
        let org = x;
        let x = (x as i64).abs();
        let reversed: String = x.to_string().chars().rev().collect();
        let mut res: i64 = reversed.parse().unwrap();
        if org < 0 {
            res *= -1;
        }
        if res < i32::MIN as i64 || res > i32::MAX as i64 {
            return 0;
        }
        res as i32
    }
}
```

